assembly_code:
LXI H, 2050H ; HL -> array size N
MOV C, M    ; C = N
DCR C       ; Outer loop count N-1
OUTER: MOV D, C ; D = inner loop count
LXI H, 2051H ; HL -> 1st element
INNER: MOV A, M ; A = current element
INX H       ; HL -> next element
CMP M       ; Compare current with next
JC NO_SWAP  ; If A < M, correct order
MOV B, M    ; Swap M and A
MOV M, A    ;
DCX H       ;
MOV M, B    ;
INX H       ;
NO_SWAP: DCR D
JNZ INNER   ;
DCR C       ;
JNZ OUTER   ;
HLT
